// ============================================================
// Build HTML (แบบ B) — ตารางผลิตรายสัปดาห์ + ผลิตจริง + กรอบเวลาที่ขยาย + cascade
// พอร์ตไปเป็น n8n Code node ได้: แทน read-from-file ด้วย $('อ่านตารางผลิต'/'อ่าน Loss'/'อ่าน map').all()
// ============================================================

// ---------- helpers ----------
const pad = (n, w) => String(n).padStart(w, '0');
const clock = d => `${d.getHours()}:${pad(d.getMinutes(), 2)}`;
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const num = v => Number(String(v==null?'':v).replace(/,/g,''))||0;
const fmt = n => Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g,',');
const fmtK = n => n>=1e6?(Math.round(n/1e5)/10+'ล.'):n>=1000?(Math.round(n/100)/10+'K'):String(Math.round(n));
const core = s => String(s??'').split('|')[0].trim();
const normMachine = m => { m=String(m??'').trim().toUpperCase(); return m==='TE1'?'TE':m; };
function toYMD(v){ if(v==null||v==='')return null; const s=String(v).trim();
  if(/^\d+(\.\d+)?$/.test(s)){const n=parseFloat(s); if(n>20000&&n<80000){const d=new Date(Date.UTC(1899,11,30)+Math.round(n)*86400000); return `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1,2)}-${pad(d.getUTCDate(),2)}`;}}
  let m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/); if(m){let Y=+m[1];if(Y>2400)Y-=543;return `${Y}-${pad(+m[2],2)}-${pad(+m[3],2)}`;}
  m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/); if(m){let Y=+m[3];if(Y>2400)Y-=543;if(Y<100)Y+=2000;return `${Y}-${pad(+m[2],2)}-${pad(+m[1],2)}`;}
  const d=new Date(s); return isNaN(d)?null:`${d.getFullYear()}-${pad(d.getMonth()+1,2)}-${pad(d.getDate(),2)}`; }
function mkDT(ymd,t){ let hh=8,mm=0; const m=String(t==null?'':t).match(/(\d{1,2}):(\d{1,2})/); if(m){hh=+m[1];mm=+m[2];} const [y,mo,d]=ymd.split('-').map(Number); return new Date(y,mo-1,d,hh,mm,0); }
const addDays=(dt,n)=>{const x=new Date(dt);x.setDate(x.getDate()+n);return x;};
const H = 3600000;                       // ms per hour
const dmy = d => `${d.getDate()}/${d.getMonth()+1}`;

// ============================================================
function computeJobs({rows, loss, mapDict, asOf}){
  const asOfDT = mkDT(asOf,'23:59');

  // ---- map: loss product -> plan core ----
  const MAP = mapDict || {};
  const mapCore = p => MAP[String(p??'').trim()] || null;

  // ---- parse jobs (รายการ T1) ----
  const jobs=[];
  for(const r of rows){
    const machine=String(r['เครื่องจักร']||'').trim(); const sdY=toYMD(r['วันที่เริ่มผลิตสินค้า']); if(!machine||!sdY)continue;
    const edY=toYMD(r['วันที่สิ้นสุดผลิตสินค้า'])||sdY;
    let st=mkDT(sdY,r['เวลาเริ่มผลิตสินค้า']), en=mkDT(edY,r['เวลาสิ้นสุดผลิตสินค้า']); if(en<=st)en=new Date(st.getTime()+H);
    const items=[];
    for(let i=1;i<=4;i++){ const nm=String(r['ชื่อสินค้า แม่พิมพ์ตัวที่ '+i]||'').trim(); if(!nm)continue; const q=num(r['จำนวนสั่งผลิต'+i]); const ex=items.find(x=>x.name===nm); if(ex)ex.qty+=q; else items.push({name:nm,qty:q}); }
    if(!items.length)items.push({name:'(ไม่ระบุ)',qty:0});
    const cores=[...new Set(items.map(it=>core(it.name)))];
    jobs.push({machine,ps:st,pe:en,items,cores,key:items.map(x=>x.name).join(' ¦ '),
               qty:items.reduce((a,it)=>a+it.qty,0), workers:num(r['จำนวนคนงาน']),
               rowNumber:(r['row_number']!=null?r['row_number']:null)});
  }

  // ---- attribute loss -> job (machine + core, latest job whose ps<=date) ----
  const byMachine={};
  for(const j of jobs){ (byMachine[j.machine]=byMachine[j.machine]||[]).push(j); }
  for(const m in byMachine) byMachine[m].sort((a,b)=>a.ps-b.ps);
  for(const j of jobs){ j.produced=0; j.daily={}; }
  for(const L of loss){
    const g=num(L['ของดี\n(ใบ)']!=null?L['ของดี\n(ใบ)']:L.good); if(!g)continue;
    const mc=normMachine(L['เครื่อง']!=null?L['เครื่อง']:L.machine);
    const cp=mapCore(L['ชื่อสินค้า']!=null?L['ชื่อสินค้า']:L.product); if(!cp)continue;
    const dy=toYMD(L['วันที่']!=null?L['วันที่']:L.date); if(!dy)continue;
    const dDT=mkDT(dy,'12:00'); if(dDT>asOfDT)continue;
    const cand=(byMachine[mc]||[]).filter(j=>j.cores.includes(cp) && j.ps<=dDT);
    if(!cand.length)continue;
    const job=cand[cand.length-1];        // latest ps<=date
    job.produced+=g; job.daily[dy]=(job.daily[dy]||0)+g;
  }

  // ---- per-job progress + projected end (worst-case rate) ----
  for(const j of jobs){
    const PH=Math.max(1,(j.pe-j.ps)/H);
    j.ratePlan = j.qty/PH;                                   // ใบ/ชม ตามแผน
    const started = j.ps<=asOfDT;
    j.remaining = Math.max(0, j.qty - j.produced);
    // อัตราจริง: ผลิตแล้ว ÷ เวลาที่ผ่านไปจริง (ถ้ายังไม่เสร็จ = ถึง asOf, ถ้าเสร็จแล้ว = ถึงปลายแผน) — window เดียวกับ produced
    const endForRate = j.remaining>0 ? asOfDT : j.pe;
    const elapsedH = started ? Math.max(1,(endForRate-j.ps)/H) : 0;
    j.rateActual = (started && j.produced>0) ? j.produced/elapsedH : null;
    // worst-case: ปกติใช้แผน ถ้าอัตราจริงแย่กว่า -> ใช้จริง
    j.rateUse = (j.rateActual!=null && j.rateActual < j.ratePlan) ? j.rateActual : j.ratePlan;
    j.pct = j.qty>0 ? Math.min(100, Math.round(j.produced/j.qty*100)) : 0;
    j.noData = started && j.produced<=0;   // เริ่มแล้วแต่ยังไม่มีข้อมูลผลิต (อาจ map ไม่ตรง/ยังไม่ลงบันทึก) — ไม่ฟันธงว่าเลท
    // projected end (ยังไม่ cascade) — ขยายเวลาเฉพาะเมื่อ "มีหลักฐานผลิตช้าจริง" (produced>0)
    if(j.remaining<=0){ j.projEndOwn = j.pe; }
    else if(started && j.produced>0){ j.projEndOwn = new Date(asOfDT.getTime() + j.remaining/j.rateUse*H); }
    else { j.projEndOwn = j.pe; }          // future / ยังไม่มีข้อมูล -> ถือตามแผน ไม่ขยาย
    j.spanH = Math.max((j.pe-j.ps)/H, (j.projEndOwn-j.ps)/H);   // ความยาวงาน (รวมขยาย)
  }

  // ---- cascade per machine: start ถัดไป = max(แผนเดิม, งานก่อนหน้า.เสร็จจริง) ----
  for(const m in byMachine){
    let cursor=null;
    for(const j of byMachine[m]){
      j.as = (cursor && cursor>j.ps) ? new Date(cursor) : new Date(j.ps);   // actual start
      j.ae = new Date(j.as.getTime() + j.spanH*H);                          // actual end
      j.shiftH = (j.as - j.ps)/H;
      j.extH = Math.max(0, (j.ae - j.pe)/H + (j.shiftH>0?0:0));             // ส่วนขยายของงานเอง (เทียบ pe)
      j.late = j.produced>0 && (j.projEndOwn - j.pe)/H > 6;                  // เลทเกิน 6 ชม. (ต้องมีข้อมูลผลิตจริง)
      j.pushed = j.shiftH > 6;
      cursor = j.ae;
    }
  }
  return {jobs, byMachine, asOfDT};
}

function renderFromComputed({jobs, byMachine, asOfDT}){

  // ---- week window = สัปดาห์ (อา.-ส.) ที่มี asOf ----
  const a=new Date(asOfDT.getFullYear(),asOfDT.getMonth(),asOfDT.getDate());
  const weekStart=addDays(a,-a.getDay());
  const days=Array.from({length:7},(_,i)=>addDays(weekStart,i));
  const winStart=new Date(days[0].getFullYear(),days[0].getMonth(),days[0].getDate());
  const TOTAL_H=7*24;
  const pctPos=ms=>(ms-winStart.getTime())/H/TOTAL_H*100;
  const inWeek=(s,e)=> e> winStart.getTime() && s < winStart.getTime()+TOTAL_H*H;

  // ---- machines & colors ----
  const PREF=['PF8/3','PF8/5','PF8/6','PF8/7','PF8/8','ASB250/3','TE'];
  const present=new Set(jobs.map(j=>j.machine));
  const machines=[...PREF,...[...present].filter(m=>!PREF.includes(m)).sort()].filter(m=>PREF.includes(m)||present.has(m));
  const PAL=[['#E8F0FE','#1967D2'],['#FCE8E6','#C5221F'],['#E6F4EA','#137333'],['#FEF7E0','#B06000'],['#F3E8FD','#8430CE'],['#E4F7FB','#00777F'],['#FDE7F3','#B80672'],['#FFF0E0','#A85400']];
  const colorOf=k=>{let h=0;for(let i=0;i<k.length;i++)h=(h*31+k.charCodeAt(i))>>>0;return PAL[h%PAL.length];};
  const THDOW=['อาทิตย์','จันทร์','อังคาร','พุธ','พฤหัส','ศุกร์','เสาร์'];
  const THMON=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
  const dstr=d=>`${d.getDate()} ${THMON[d.getMonth()]}`;
  const rangeLabel=`${dstr(days[0])} – ${dstr(days[6])} ${days[6].getFullYear()+543}`;
  const dayHead=days.map(d=>{const wk=d.getDay()===0||d.getDay()===6;return `<div class="dh${wk?' we':''}"><div class="dow">${THDOW[d.getDay()]}</div><div class="dnum">${d.getDate()}/${d.getMonth()+1}</div></div>`;}).join('');

  // ---- render rows ----
  let anyLate=false, anyPushed=false;
  const rowsHtml=machines.map(m=>{
    const mine=(byMachine[m]||[]).slice().sort((x,y)=>x.as-y.as);
    let bars='';
    for(const j of mine){
      const [bg,fg]=colorOf(j.key);
      const asMs=j.as.getTime(), aeMs=j.ae.getTime(), peMs=j.pe.getTime(), psMs=j.ps.getTime();
      if(!inWeek(Math.min(asMs,psMs),aeMs)) continue;
      const L=Math.max(0,pctPos(asMs)), R=Math.min(100,pctPos(aeMs)); const W=Math.max(0.8,R-L);
      const wide=W>7;
      // ghost (ตำแหน่งเดิม) ถ้าโดนเลื่อน
      let ghost='';
      if(j.pushed){ anyPushed=true; const gL=Math.max(0,pctPos(psMs)),gR=Math.min(100,pctPos(peMs)); const gW=Math.max(2,gR-gL);
        ghost=`<div class="ghost" style="left:${gL}%;width:${gW}%"><span>เดิม ${dmy(j.ps)}–${dmy(j.pe)}</span></div>`; }
      // extension overlay: ส่วน [pe..ae] (เทียบตำแหน่งจริง as+span)
      let ext='';
      const extStartMs = j.as.getTime() + Math.max(0,(peMs-psMs))/1*1 ; // = as + plannedSpan
      const extS = j.as.getTime() + (peMs-psMs);                         // ปลายแผน (เลื่อนตาม as)
      if(j.late && extS<aeMs){ anyLate=true;
        const eL=Math.max(0,pctPos(extS)), eR=Math.min(100,pctPos(aeMs)); const eW=Math.max(0.6,eR-eL);
        const extDays=Math.round((aeMs-extS)/H/24*10)/10;
        ext=`<div class="extf" style="left:${eL}%;width:${eW}%"><span>+${extDays} วัน</span></div>`; }
      // daily numbers (ล่าสุด ≤5) ถ้ากว้างพอ
      const dseq=Object.keys(j.daily).sort().map(d=>({d,v:j.daily[d]}));
      const dailyTxt = (wide && dseq.length)? `<div class="bday">ผลิต: ${dseq.slice(-6).map(x=>fmtK(x.v)).join(' · ')}</div>` : '';
      const prodLines=j.items.map(it=>`<div class="bn" style="color:${fg}">${esc(it.name.split('|')[0].trim())}${it.qty?` <span class="q">${fmtK(it.qty)} ใบ</span>`:''}</div>`).slice(0,2).join('');
      const chip = j.pct>0? `<span class="chip" style="color:${fg};border-color:${fg}">ทำแล้ว ${j.pct}%</span>`:'';
      const tag = j.late? `<span class="tag">▼ เลท</span>` : (j.pushed? `<span class="tag push">→ เลื่อน</span>`:'');
      // fill = สัดส่วนที่ผลิตแล้ว วางบนช่วง "ตามแผน" ของแท่ง (ไม่รวมส่วนขยาย)
      const plannedFrac = Math.max(0,Math.min(1,(peMs-asMs)/(aeMs-asMs)));
      const fillW = Math.round(j.pct*plannedFrac);
      const fill = j.pct>0? `<div class="fill" style="width:${fillW}%;background:${fg}22"></div>`:'';
      bars += `${ghost}<div class="bar${wide?'':' narrow'}" style="left:${L}%;width:${W}%;background:${bg};border-color:${fg}">
        ${fill}<div class="binner">${prodLines}${chip}${tag}${dailyTxt}</div></div>${ext}`;
    }
    const idle=mine.length?'':'<div class="idle">ว่าง</div>';
    return `<div class="row"><div class="mlabel">${esc(m)}</div><div class="track">${bars}${idle}</div></div>`;
  }).join('');

  const totalQty=jobs.reduce((s,j)=>s+j.qty,0);
  const totalProd=jobs.reduce((s,j)=>s+j.produced,0);
  const lateN=jobs.filter(j=>j.late).length;

  return `<!doctype html><html lang="th"><head><meta charset="utf-8"><style>
*{box-sizing:border-box;margin:0;padding:0}
#cap{width:2200px;background:#fff;font-family:'Noto Sans Thai','Sarabun',sans-serif;color:#1f2733}
.head{background:linear-gradient(90deg,#1A237E,#283593);color:#fff;padding:20px 26px;display:flex;align-items:center;justify-content:space-between}
.head .t{font-size:26px;font-weight:800}.head .s{font-size:15px;color:#C5CAE9;margin-top:3px}
.head .r{text-align:right;font-size:13px;color:#9FA8DA}
.wrap{padding:14px 18px 18px}
.sum{display:flex;gap:26px;flex-wrap:wrap;margin-bottom:12px}
.sum .box{flex:1;min-width:170px;background:#F4F7FC;border:1px solid #E3E7EE;border-left:5px solid #1A237E;border-radius:9px;padding:11px 15px}
.sum .box.warn{border-left-color:#C5221F}
.sum .box .lab{font-size:12.5px;color:#6B7280}.sum .box .val{font-size:22px;font-weight:800;color:#1A237E;margin-top:2px}
.sum .box.warn .val{color:#C5221F}.sum .box .val span{font-size:13px;font-weight:600;color:#6B7280}
.grid{border:1px solid #E3E7EE;border-radius:10px;overflow:hidden}
.ghead{display:grid;grid-template-columns:130px 1fr;background:#F7F9FC;border-bottom:2px solid #E3E7EE}
.corner{padding:10px;font-weight:700;color:#5B6472;display:flex;align-items:center;justify-content:center;border-right:1px solid #E3E7EE}
.days{display:grid;grid-template-columns:repeat(7,1fr)}
.dh{padding:8px 4px;text-align:center;border-right:1px solid #E3E7EE}.dh:last-child{border-right:0}.dh.we{background:#FBEFEA}
.dh .dow{font-weight:700;font-size:14px}.dh .dnum{font-size:12px;color:#6B7280;margin-top:2px}
.row{display:grid;grid-template-columns:130px 1fr;border-bottom:1px solid #EEF1F5;min-height:104px}.row:last-child{border-bottom:0}
.mlabel{display:flex;align-items:center;justify-content:center;font-weight:700;font-size:14px;color:#263238;background:#F7F9FC;border-right:1px solid #E3E7EE;padding:6px}
.track{position:relative;background:
  repeating-linear-gradient(90deg,transparent 0,transparent calc(100%/7 - 1px),#E9EDF3 calc(100%/7 - 1px),#E9EDF3 calc(100%/7)),
  repeating-linear-gradient(90deg,transparent 0,transparent calc(100%/28 - 1px),#F4F6FA calc(100%/28 - 1px),#F4F6FA calc(100%/28));min-height:104px}
.bar{position:absolute;top:8px;height:60px;border-left:4px solid;border-radius:6px;overflow:hidden;box-shadow:0 1px 2px rgba(20,30,50,.08)}
.bar .fill{position:absolute;left:0;top:0;bottom:0;z-index:0}
.binner{position:relative;z-index:1;padding:5px 8px}
.bar .bn{font-weight:800;font-size:13px;line-height:1.16}
.bar .bn .q{font-weight:600;font-size:.82em;opacity:.92}
.chip{display:inline-block;font-size:10.5px;font-weight:800;border:1.5px solid;border-radius:20px;padding:0 7px;margin-top:3px;background:#ffffffcc}
.tag{display:inline-block;font-size:10.5px;font-weight:800;color:#fff;background:#C5221F;border-radius:5px;padding:1px 7px;margin-top:3px;margin-left:4px}
.tag.push{background:#B06000}
.bday{font-size:10.5px;color:#5B6472;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bar.narrow .bn{font-size:11px}.bar.narrow .binner{padding:4px 5px}
.ghost{position:absolute;top:74px;height:22px;border:2px dashed #AEB4BD;border-radius:5px;background:transparent;display:flex;align-items:center;justify-content:center}
.ghost span{font-size:10px;color:#9AA3AF;font-weight:700;white-space:nowrap}
.extf{position:absolute;top:8px;height:60px;border:2px dashed #C5221F;border-radius:6px;
  background:repeating-linear-gradient(45deg,rgba(197,34,31,.05) 0,rgba(197,34,31,.05) 6px,rgba(197,34,31,.11) 6px,rgba(197,34,31,.11) 12px);
  display:flex;align-items:center;justify-content:center;z-index:2}
.extf span{font-size:11px;font-weight:800;color:#C5221F;text-align:center;line-height:1.1}
.idle{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#AEB4BD;font-size:13px}
.legend{display:flex;flex-wrap:wrap;gap:10px 18px;padding:12px 4px 2px;font-size:12.5px;color:#5B6472}
.legend .k{display:flex;align-items:center;gap:6px}.legend .sw{width:16px;height:16px;border-radius:4px;border:2px solid}
.legend .sw.dash{border-style:dashed}
.note{font-size:12px;color:#8A929E;margin-top:6px}
</style></head><body><div id="cap">
  <div class="head"><div><div class="t">ตารางการผลิตประจำสัปดาห์ — ความคืบหน้าจริง</div><div class="s">TPI · ${rangeLabel} · ข้อมูล ณ ${asOfDT.getDate()}/${asOfDT.getMonth()+1}</div></div>
  <div class="r">แถบทึบ = แผนหลังคิดผลจริง · กรอบแดง = เวลาที่ขยาย<br>กรอบเทา = ตำแหน่งเดิมก่อนเลื่อน</div></div>
  <div class="wrap">
    <div class="sum">
      <div class="box"><div class="lab">ยอดที่ต้องผลิตรวมสัปดาห์</div><div class="val">${fmt(totalQty)} <span>ใบ</span></div></div>
      <div class="box"><div class="lab">ผลิตแล้วรวม (จาก Loss)</div><div class="val">${fmt(totalProd)} <span>ใบ</span></div></div>
      <div class="box${lateN?' warn':''}"><div class="lab">งานที่ต่ำกว่าเป้า/ต้องขยายเวลา</div><div class="val">${lateN} <span>งาน</span></div></div>
    </div>
    <div class="grid"><div class="ghead"><div class="corner">เครื่องจักร</div><div class="days">${dayHead}</div></div>${rowsHtml}</div>
    <div class="legend">
      <div class="k"><span class="sw" style="border-color:#137333;background:#E6F4EA"></span>แถบทึบ = งาน (แรเงา = สัดส่วนที่ผลิตแล้ว)</div>
      <div class="k"><span class="sw dash" style="border-color:#C5221F"></span>กรอบแดง = ช่วงเวลาที่ขยาย (ผลิตไม่ทันเป้า)</div>
      <div class="k"><span class="sw dash" style="border-color:#AEB4BD"></span>กรอบเทา = ตำแหน่งเดิมตามแผน (ก่อนเลื่อน)</div>
    </div>
    <div class="note">* ยอดผลิตจริงรายวันจากชีต Loss report "2026" (ของดี/วัน) · เวลาขยาย = คงเหลือ ÷ อัตราผลิต (แผนหรือจริงที่แย่กว่า) · เลื่อนงานถัดไป = งานก่อนหน้าเสร็จช้า</div>
  </div>
</div></body></html>`;
}

function buildHtml(input){ return renderFromComputed(computeJobs(input)); }

// ---- write-back rows (อัปเดตในที่ ตาม row_number) ----
const fmtYMD2=dt=>`${dt.getFullYear()}-${pad(dt.getMonth()+1,2)}-${pad(dt.getDate(),2)}`;
const fmtHM=dt=>`${pad(dt.getHours(),2)}:${pad(dt.getMinutes(),2)}`;
const fmtDMY2=dt=>`${dt.getDate()}/${dt.getMonth()+1}/${dt.getFullYear()}`;

// รายการ T1: อัปเดต start/end เฉพาะงานที่ schedule เปลี่ยน (เลื่อน/ขยาย)
function raykWriteRows(jobs){
  const out=[];
  for(const j of jobs){
    if(!(j.late||j.pushed)) continue;
    if(j.rowNumber==null) continue;
    out.push({row_number:j.rowNumber,
      'วันที่เริ่มผลิตสินค้า':fmtYMD2(j.as),'เวลาเริ่มผลิตสินค้า':fmtHM(j.as),
      'วันที่สิ้นสุดผลิตสินค้า':fmtYMD2(j.ae),'เวลาสิ้นสุดผลิตสินค้า':fmtHM(j.ae)});
  }
  return out;
}

// Planning: จับแถว (เครื่อง+core) -> งานที่เลื่อน -> อัปเดต วันที่ผลิต = เริ่มจริงใหม่ (as)
function planWriteRows(jobs, planningRows){
  const out=[];
  for(const r of (planningRows||[])){
    if(r['row_number']==null) continue;
    const pm=normMachine(r['เครื่องจักร']); const pc=core(r['ชื่อสินค้า']);
    const cand=jobs.filter(j=>(j.late||j.pushed)&&normMachine(j.machine)===pm&&j.cores.includes(pc));
    if(!cand.length) continue;
    const pd=toYMD(r['วันที่ผลิต']);
    let job=cand[0];
    if(pd){ const pdMs=mkDT(pd,'00:00').getTime(); job=cand.reduce((b,j)=>Math.abs(j.ps-pdMs)<Math.abs(b.ps-pdMs)?j:b,cand[0]); }
    out.push({row_number:r['row_number'],'วันที่ผลิต':fmtDMY2(job.as)});
  }
  return out;
}

