const SUMMARY_DAYS = 1;

const pad2 = n => String(n).padStart(2, '0');

const num = v =>
  Number(String(v == null ? '' : v).replace(/,/g, '')) || 0;


// ============================================================
// หา "วันนี้" ตามเวลาไทยโดยตรง
// ไม่อิง timezone ของ server
