// ============================================================
// Convert วันที่จาก Google Sheet -> YYYY-MM-DD
// ============================================================
function toYMD(v) {

  if (v == null || v === '') return null;

  const s = String(v).trim();


  // Google Sheets serial date
  if (/^\d+(\.\d+)?$/.test(s)) {

    const n = parseFloat(s);

    if (n > 20000 && n < 80000) {

      const d = new Date(
        Date.UTC(1899, 11, 30) +
        Math.floor(n) * 86400000
      );

      return (
        d.getUTCFullYear() + '-' +
        pad2(d.getUTCMonth() + 1) + '-' +
        pad2(d.getUTCDate())
      );
    }
  }


  // YYYY-MM-DD
  let m = s.match(
    /^(\d{4})-(\d{1,2})-(\d{1,2})/
  );

  if (m) {

    let Y = +m[1];

    if (Y > 2400) Y -= 543;

    return (
      Y + '-' +
      pad2(+m[2]) + '-' +
      pad2(+m[3])
    );
  }


  // DD/MM/YYYY
  m = s.match(
    /^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/
  );

  if (m) {

    let Y = +m[3];

    if (Y > 2400) Y -= 543;
    if (Y < 100) Y += 2000;

    return (
      Y + '-' +
      pad2(+m[2]) + '-' +
      pad2(+m[1])
    );
  }


  return null;
}


// ============================================================
// สร้าง Date แบบ UTC
//
// เราใช้ UTC เป็นตัวแทน "เวลาโรงงาน"
// เพื่อไม่ให้ timezone ของ Server มาเลื่อนเวลา
// ============================================================
function mkDT(ymd, t) {

  if (!ymd) return null;

  let hh = 8;
  let mm = 0;

  const m = String(
    t == null ? '' : t
  ).match(/(\d{1,2}):(\d{1,2})/);

  if (m) {
    hh = +m[1];
    mm = +m[2];
  }

  const [y, mo, d] =
    ymd.split('-').map(Number);

  return new Date(
    Date.UTC(
      y,
      mo - 1,
      d,
      hh,
      mm,
      0
    )
  );
}


// ============================================================
// สร้างข้อความสรุปกะ
// ============================================================
function buildShiftSummary(jobs, asOfYMD) {

  const beYY = d =>
    pad2(
      (d.getUTCFullYear() + 543) % 100
    );

  const dLabel = d =>
    `${d.getUTCDate()}/${d.getUTCMonth() + 1}/${beYY(d)}`;

  const hm = d =>
    `${pad2(d.getUTCHours())}:${pad2(d.getUTCMinutes())}`;

  const SHIFTS = [
    { n: 1, h: 6 },
    { n: 2, h: 14 },
    { n: 3, h: 22 }
  ];

  const SEP =
    '--------------------------------------';


  // วันนี้ เวลา 00:00
  const a =
    mkDT(asOfYMD, '00:00');

  const blocks = [];


  // ==========================================================
  // Loop วัน
  // ==========================================================
  for (
    let di = 0;
    di < SUMMARY_DAYS;
    di++
  ) {

    const day =
      new Date(
        a.getTime() +
        di * 24 * 3600000
      );


    // ========================================================
    // Loop กะ
    // ========================================================
    for (const sh of SHIFTS) {

      const S =
        new Date(
          Date.UTC(
            day.getUTCFullYear(),
            day.getUTCMonth(),
            day.getUTCDate(),
            sh.h,
            0,
            0
          )
        );


      // กะละ 8 ชั่วโมง
      const E =
        new Date(
          S.getTime() +
          8 * 3600000
        );


      // งานที่ทับกับช่วงกะนี้
      const inShift =
        jobs.filter(
          j =>
            j.as < E &&
            j.ae > S
        );


      if (!inShift.length) {
        continue;
      }


      // ======================================================
      // หาจำนวนคนสูงสุดพร้อมกัน
      // ======================================================
      const evts = [];

      for (const j of inShift) {

        const s =
          Math.max(
            S.getTime(),
            j.as.getTime()
          );

        const e =
          Math.min(
            E.getTime(),
            j.ae.getTime()
          );


        if (e <= s) continue;


        evts.push([
          s,
          +j.workers
        ]);

        evts.push([
          e,
          -j.workers
        ]);
      }


      // เวลาเดียวกัน:
      // จบงานก่อน แล้วค่อยเริ่มงานใหม่
      evts.sort(
        (x, y) =>
          x[0] - y[0] ||
          x[1] - y[1]
      );


      let cur = 0;
      let mx = 0;

      for (const [, w] of evts) {

        cur += w;

        if (cur > mx) {
          mx = cur;
        }
      }


      // ======================================================
      // Group ตามเครื่อง
      // ======================================================
      const byM = {};

      for (const j of inShift) {

        if (!byM[j.machine]) {
          byM[j.machine] = [];
        }

        byM[j.machine].push(j);
      }


      const machs =
        Object.keys(byM).sort(
          (x, y) => {

            const tx =
              Math.min(
                ...byM[x].map(
                  j => j.as.getTime()
                )
              );

            const ty =
              Math.min(
                ...byM[y].map(
                  j => j.as.getTime()
                )
              );

            return tx - ty;
          }
        );


      // ======================================================
      // สร้างข้อความแต่ละเครื่อง
      // ======================================================
      const lines =
        machs.map(m => {

          const js =
            byM[m].sort(
              (x, y) =>
                x.as - y.as
            );


          const w =
            Math.max(
              ...js.map(
                j => j.workers
              )
            );


          const first =
            js[0];


          let note = '';


          // ==================================================
          // ตรวจ handoff
          // ==================================================
          if (
            first.as.getTime() >
            S.getTime() + 60000
          ) {

            const pred =
              inShift
                .filter(
                  j =>
                    j.machine !== m &&

                    Math.abs(
                      j.ae.getTime() -
                      first.as.getTime()
                    ) <= 60000 &&

                    j.ae.getTime() >=
                    S.getTime()
                )
                .sort(
                  (x, y) =>
                    y.ae - x.ae
                )[0];


            if (pred) {

              note =
                ` (เริ่มทำต่อจาก ${pred.machine}` +
                ` ครบ ตอนเวลา ${hm(first.as)})`;
            }
          }


          return (
            `- เครื่อง ${String(m).padEnd(8)}` +
            `= ${w} คน${note}`
          );
        });


      // ======================================================
      // Header ของแต่ละกะ
      // ======================================================
      blocks.push(
        `วันที่ ${dLabel(day)} รอบ ${sh.n}\n\n` +
        `มีพนักงานเครื่อง = ${mx} คน\n\n` +
        lines.join('\n')
      );
    }
  }


  // ==========================================================
  // ไม่มีงาน
  // ==========================================================
  if (!blocks.length) {

    const [
      y,
      m,
      d
    ] =
      asOfYMD.split('-');

    return (
      `ไม่มีงานผลิตในวันที่ ` +
      `${Number(d)}/${Number(m)}/${y}`
    );
  }


  // ==========================================================
  // LINE จำกัดข้อความ
  // ==========================================================
  const MAX = 4800;

  let text = '';
  let cut = false;


  for (const b of blocks) {

    const next =
      text
        ? text +
          `\n${SEP}\n\n` +
          b
        : b;


    if (next.length > MAX) {
      cut = true;
      break;
    }


    text = next;
  }


  if (cut) {

    text +=
      `\n${SEP}\n\n` +
      `(สรุปต่อได้ไม่หมดในข้อความเดียว — ` +
      `ดูรายละเอียดที่เหลือในรูป)`;
  }


  return text;
}


