// ============================================================
// สร้าง jobs
// ============================================================
const jobs = [];


for (const r of rows) {

  const machine =
    String(
      r['เครื่องจักร'] || ''
    ).trim();


  const sd =
    toYMD(
      r['วันที่เริ่มผลิตสินค้า']
    );


  if (!machine || !sd) {
    continue;
  }


  const ed =
    toYMD(
      r['วันที่สิ้นสุดผลิตสินค้า']
    ) || sd;


  let as =
    mkDT(
      sd,
      r['เวลาเริ่มผลิตสินค้า']
    );


  let ae =
    mkDT(
      ed,
      r['เวลาสิ้นสุดผลิตสินค้า']
    );


  if (!as || !ae) {
    continue;
  }


  // ป้องกันเวลาจบ <= เวลาเริ่ม
  if (ae <= as) {

    ae =
      new Date(
        as.getTime() +
        3600000
      );
  }


  jobs.push({
    machine,
    as,
    ae,
    workers:
      num(
        r['จำนวนคนงาน']
      ) || 1
  });
}


