// แปลงลิงก์รูป — permanent shared link -> raw + ดัก 409 shared_link_already_exists
// รับ output จากโหนด "Create shared link" (create_shared_link_with_settings, neverError:true)
//   สำเร็จ (200):            { url, ... }
//   ลิงก์มีอยู่แล้ว (409):    { error_summary, error:{ ".tag":"shared_link_already_exists", shared_link_already_exists:{ metadata:{ url } } } }
// คืน { ...passthru, link } เพื่อให้ "สรุปกะ (ข้อความ)" ส่งต่อ แล้ว "Send LINE image" ใช้ $json.link ได้เหมือนเดิม (ไม่ต้องแก้ 2 โหนดนั้น)
// ห่อ IIFE กัน n8n 2.10.4 คอมไพล์ source ซ้ำ 2 รอบ (top-level const ชนตัวเอง)
return (function () {
  const j = ($input.first() && $input.first().json) ? $input.first().json : {};

  // 1) หา url — จาก success หรือดึงจาก error 409 (ลิงก์เคยสร้างไว้แล้ว = วันเดิมรันซ้ำ)
  let url = j.url || null;
  if (!url && j.error && j.error['.tag'] === 'shared_link_already_exists') {
    url = j.error.shared_link_already_exists
      && j.error.shared_link_already_exists.metadata
      && j.error.shared_link_already_exists.metadata.url;
  }
  if (!url) {
    // error อื่น (เช่น missing_scope/sharing.write, path/not_found) -> โยนให้เห็นชัด
    throw new Error('Create shared link ไม่คืน url — ' + (j.error_summary || JSON.stringify(j).slice(0, 300)));
  }

  // 2) permanent link -> raw : ให้ Dropbox เสิร์ฟไบต์รูปผ่านลิงก์ถาวร (ไม่หมดอายุ 4 ชม.เหมือน temp link)
  //    permanent link มาแบบ https://www.dropbox.com/scl/fi/.../<name>?rlkey=...&st=...&dl=0
  //    สลับ dl=0 -> raw=1 (ถ้าไม่มี dl ให้เติม raw=1)
  //    * fallback ถ้าบางที่ยังแตก: link = link.replace('www.dropbox.com','dl.dropboxusercontent.com')
  let link = String(url);
  if (/[?&]dl=\d/.test(link)) link = link.replace(/([?&])dl=\d/, '$1raw=1');
  else if (!/[?&]raw=1/.test(link)) link += (link.includes('?') ? '&' : '?') + 'raw=1';

  return [{ json: { ...j, link } }];
})();
